<?php
session_start();require_once '../shared/config.php';require_once '../shared/security.php';o2oCsrfToken();requireLogin('vendor','login.php');$db=getDB();$vendorId=(int)$_SESSION['vendor_id'];
$st=$db->prepare("SELECT c.id,c.name,c.email,c.phone,c.pincode,MAX(x.created_at) last_order,COUNT(*) order_count
FROM customers c JOIN (
 SELECT customer_id,created_at FROM orders WHERE vendor_id=?
 UNION ALL SELECT customer_id,created_at FROM purchase_orders WHERE vendor_id=?
) x ON x.customer_id=c.id GROUP BY c.id ORDER BY last_order DESC LIMIT 200");
$st->execute([$vendorId,$vendorId]);$customers=$st->fetchAll();
?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customers – O2O Tradition</title><style>body{font-family:Arial;background:#F4F7F4;color:#1A2E1A;margin:0}.nav{background:#0F1B2D;color:#C9A84C;padding:18px 28px;display:flex;justify-content:space-between}.nav a{color:#E8CC82;text-decoration:none;margin-left:15px}.main{max-width:1100px;margin:auto;padding:30px}.card{background:#fff;border:1px solid #DDE5DD;padding:20px}.table{width:100%;border-collapse:collapse;font-size:13px}.table th,.table td{padding:11px;border-bottom:1px solid #eee;text-align:left}.muted{color:#777;font-size:12px}</style></head><body><div class="nav"><b>O2O Tradition · Customers</b><div><a href="dashboard.php">Dashboard</a><a href="notifications.php">Notifications</a><a href="logout.php">Logout</a></div></div><main class="main"><h1>Customers</h1><p class="muted">Customers who have placed rental or buy orders with your store. Contact details are shown only to the authenticated vendor.</p><section class="card"><div style="overflow:auto"><table class="table"><tr><th>Customer</th><th>Phone</th><th>Pincode</th><th>Orders</th><th>Last Order</th></tr><?php foreach($customers as $c):?><tr><td><b><?=htmlspecialchars($c['name'])?></b><br><span class="muted"><?=htmlspecialchars($c['email'])?></span></td><td><?=htmlspecialchars($c['phone']??'—')?></td><td><?=htmlspecialchars($c['pincode']??'—')?></td><td><?=intval($c['order_count'])?></td><td><?=date('d M Y, h:i A',strtotime($c['last_order']))?></td></tr><?php endforeach;if(!$customers):?><tr><td colspan="5">No customers yet.</td></tr><?php endif;?></table></div></section></main></body></html>